properties.description:
Detects rundll32.exe processes making outbound network connections to non-RFC1918
destinations. Legitimate rundll32 should rarely contact the internet directly;
this pattern is a hallmark of CobaltStrike, IcedID, and Qakbot loaders.

properties.query:
// Loader families that abuse rundll32 for C2 overwhelmingly use these ports.
// Restricting to them keeps volume manageable; widen deliberately and watch the
// alert count (see tuningGuidance).
let suspicious_ports = dynamic([80, 443, 8080, 8443, 53]);
let proc =
  DeviceProcessEvents
  | where TimeGenerated > ago(1h)
  | where FileName =~ "rundll32.exe"
  | project ProcTime = TimeGenerated, DeviceId, DeviceName, ProcessId,
            InitiatingProcessFileName, ProcessCommandLine, AccountName;
let net =
  DeviceNetworkEvents
  | where TimeGenerated > ago(1h)
  | where InitiatingProcessFileName =~ "rundll32.exe"
  | where RemoteIPType !in ("Private","Loopback","LinkLocal","Reserved")
  | where isnotempty(RemoteIP)
  // RemotePort is dynamic in DeviceNetworkEvents; cast before the set membership
  // test so the filter behaves predictably across connector schemas.
  | where toint(RemotePort) in (suspicious_ports)
  | project NetTime = TimeGenerated, DeviceId, InitiatingProcessId,
            RemoteIP, RemotePort, RemoteUrl;
proc
| join kind=inner net on DeviceId, $left.ProcessId == $right.InitiatingProcessId
| where NetTime between (ProcTime .. (ProcTime + 10m))
| project TimeGenerated = NetTime, ProcTime, DeviceId, DeviceName, AccountName, ProcessCommandLine,
          RemoteIP, RemotePort, RemoteUrl, InitiatingProcessFileName
